head.script:
// 테스트 설명, 유효성 값 설정
//  ★ _8 : 공백 Row / 좌우 공백 처리 옵션(skipSpace / readUntilEmptyRow / trim). description 은 분리 샘플 공통.
scwin.tData = {
    "description" : "[gridView > M > advancedExcelUpload]<br/>Excel 파일을 업로드하여 GridView 의 데이터로 설정합니다.",
    "validation" : [
        "skipSpace(선택) 파라미터로 Excel 데이터에서 공백인 Row 를 생략할지 설정합니다.",
        "skipSpace(선택) 파라미터를 '0' 으로 설정 시 공백인 Row 를 데이터로 추가합니다.",
        "skipSpace(선택) 파라미터를 '1' 로 설정 시 공백인 Row 는 생략하고 데이터로 추가하지 않습니다.",
        "skipSpace(선택) 파라미터에서 공백인 Row 데이터는 모든 Column 값이 빈 문자열인 Row 를 의미합니다.",
        "skipSpace(선택) 파라미터를 생략하면 기본값 '0' 으로 동작합니다.",
        "readUntilEmptyRow(선택) 파라미터로 Excel 데이터에서 공백인 Row 를 처리하는 방식을 설정합니다.",
        "readUntilEmptyRow(선택) 파라미터를 '0' 으로 설정 시 skipSpace 파라미터값에 따라 공백인 Row 를 데이터로 처리하거나 무시합니다.",
        "readUntilEmptyRow(선택) 파라미터를 '1' 로 설정 시 공백인 Row 의 이전 Row 까지 데이터로 처리하고 공백인 Row 이후 Row 는 무시합니다.",
        "readUntilEmptyRow(선택) 파라미터를 '1' 로 설정하면 skipSpace 파라미터는 무시됩니다.",
        "readUntilEmptyRow(선택) 파라미터를 생략하면 기본값 '0' 으로 동작합니다.",
        "trim(선택) 파라미터로 Excel 의 각 Column 데이터에서 좌우 공백을 제거할지 설정합니다.",
        "trim(선택) 파라미터를 '0' 으로 설정 시 Column 데이터의 좌우 공백을 유지합니다.",
        "trim(선택) 파라미터를 '1' 로 설정 시 Column 데이터의 좌우 공백을 제거합니다.",
        "trim(선택) 파라미터를 생략하면 기본값 '0' 으로 동작합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 : DataList 가 바인딩된 4 Column GridView 를 동적 생성한다.
//  · advancedExcelUpload 는 DataList 바인딩이 전제 조건이므로 dataList 속성을 반드시 설정한다.
//  · footerExist 기본값("1")의 간섭을 배제하기 위해 Footer 가 없는 그리드로 구성한다.
//  · append 는 미설정(기본값 "0") 으로 동작하므로 업로드 후 Row 수는 Excel 에서 반영된 Row 수와 같다.
scwin.comp_init = async function () {
    // 기존 target / DataList 정리
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove(dlt_bind.id);
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제]\n- name1~name4 4개 Column 그리드에 DataList 가 바인딩되어 있음 (Footer 없음)\n- 테스트용 Excel : TSQA/src/sample/gridView/data/upload/ts_gridView_M_advancedExcelUpload_8/ts_gridView_M_advancedExcelUpload_8_upload.xlsx\n- Excel 구성(6행)\n  0행 : xls0_1 / xls0_2 / xls0_3 / xls0_4\n  1행 : (공백2칸)xls1_1(공백2칸) / (공백2칸)xls1_2(공백2칸) / xls1_3 / xls1_4\n  2행 : 모든 Column 이 빈 문자열인 공백 Row\n  3행 : xls3_1 / (빈값) / (빈값) / xls3_4  (일부 Column 만 빈값이라 공백 Row 아님)\n  4행 : 모든 Column 이 빈 문자열인 공백 Row\n  5행 : xls5_1 / xls5_2 / xls5_3 / xls5_4\n- 각 Cell 값에 Excel 원본 Row 인덱스가 들어 있어 업로드된 값만으로 원본 Row 를 판별할 수 있음\n- append 는 미설정(기본값)이라 업로드 시 기존 데이터가 삭제되고 Excel 데이터만 남음\n- wframe 파라미터는 미설정(기본값)이라 Excel 파일 선택 팝업창이 별도 팝업 창으로 열림\n[절차]\n1. Target 재생성 버튼으로 그리드를 초기 상태로 되돌린다\n2. par 옵션(skipSpace / readUntilEmptyRow / trim) 값을 선택한다\n3. advancedExcelUpload 버튼을 클릭한다\n4. 열린 팝업 창에서 위 Excel 파일을 선택하고 File Upload 를 실행한다\n5. 업로드결과확인 버튼을 클릭한다\n6. 다른 옵션값을 확인하려면 1번부터 반복한다\n[확인]\n- 5번 출력의 GridView Row 수로 공백 Row 처리 결과를 구분한다\n- 5번 출력에 xls3_1 로 시작하는 Row 가 남아 있는지로 일부 Column 만 빈값인 Row 가 공백 Row 로 취급되지 않음을 확인한다\n- 5번 출력은 각 Cell 값을 대괄호로 감싸고 뒤에 문자 길이를 표시하므로 xls1_1 / xls1_2 값의 좌우 공백 유지 여부를 길이로 확인한다"', '', 'label1');

    // DataList 생성 (col1~col4 / 4행)
    await $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성 (DataList 바인딩 / Footer 없음)
    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:' + dlt_bind.id + '" checkAllType="false" id="" style="width:500px;height:300px;">';
    strTarget += '<w2:header style="" id="header1"><w2:row style="" id="row1">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="hcol1" value="name1"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="hcol2" value="name2"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="hcol3" value="name3"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="hcol4" value="name4"></w2:column>';
    strTarget += '</w2:row></w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1"><w2:row style="" id="row2">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col2" dataList="col2"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col3" dataList="col3"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col4" dataList="col4"></w2:column>';
    strTarget += '</w2:row></w2:gBody>';
    strTarget += '</w2:gridView>';
    scwin["target1"] = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// par 옵션값으로 advancedExcelUpload options 객체를 구성한다.
//  · 선택(필수여부 N) 파라미터는 미설정(빈값) 이면 객체에 담지 않아 생략되도록 한다.
//  · wframe 은 본 샘플의 검증 대상이 아니므로 미설정(기본값) 으로 두어 업로드 창을 별도 팝업 창으로 연다.
scwin.buildOptions = function () {
    let options = {};
    let v;

    v = par_skipSpace.getValue();
    if (v !== "") options.skipSpace = v;

    v = par_readUntilEmptyRow.getValue();
    if (v !== "") options.readUntilEmptyRow = v;

    v = par_trim.getValue();
    if (v !== "") options.trim = v;

    return options;
}



// advancedExcelUpload 실행
scwin.btn_advancedExcelUpload_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    target1.advancedExcelUpload(scwin.buildOptions());
}



// 업로드 결과 확인 : GridView 에 실제 반영된 Row 수와 Row 별 데이터를 출력한다.
//  · Row 수로 공백 Row 처리 결과를 판별한다.
//  · 좌우 공백은 화면상 구분되지 않으므로 각 Cell 값을 대괄호로 감싸고 문자 길이를 함께 출력한다.
scwin.btn_getResult_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.setReturnValue("=====btn_getResult_onclick=====");

    let cnt = target1.getRowCount();
    bottom.setReturnValue("GridView Row 수 : " + cnt);
    for (let i = 0; i < cnt; i++) {
        let v1 = target1.getCellData(i, "col1") + "";
        let v2 = target1.getCellData(i, "col2") + "";
        let v3 = target1.getCellData(i, "col3") + "";
        let v4 = target1.getCellData(i, "col4") + "";
        bottom.setReturnValue("[" + i + "] [" + v1 + "](" + v1.length + ") | [" + v2 + "](" + v2.length + ") | [" + v3 + "](" + v3.length + ") | [" + v4 + "](" + v4.length + ")");
    }
}
